<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../api/client';const items=ref<any[]>([]),properties=ref<any[]>([]),tenants=ref<any[]>([]),showModal=ref(false),form=ref({PropertyID:'',TenantID:'',Description:''});async function load(){const[w,p,t]=await Promise.all([api.get('/work-orders',{params:{page:1,page_size:100}}),api.get('/properties',{params:{page:1,page_size:100}}),api.get('/tenants',{params:{page:1,page_size:100}})]);items.value=w.data.items||[];properties.value=p.data.items||[];tenants.value=t.data.items||[]}async function add(){await api.post('/work-orders',form.value);showModal.value=false;await load()}async function assign(id:string){const assignee_id=prompt('请输入维修人员 ID')||'';if(assignee_id){await api.post(`/work-orders/${id}/assign`,{assignee_id});await load()}}async function transition(id:string,status:string){await api.post(`/work-orders/${id}/transition`,{status,reason:'管理后台维修操作'});await load()}async function confirm(id:string){await api.post(`/work-orders/${id}/confirm`);await load()}function propertyName(id:string){const x=properties.value.find(v=>v.ID===id);return x?`${x.Building} ${x.Room}`:id.slice(0,8)}onMounted(load)</script><template><div class="page"><div class="page-title"><div><h1>维修工单</h1><p>从租客报修、派单、维修、材料费用到租客确认形成闭环</p></div><button class="primary-button" @click="showModal=true">＋ 新增报修</button></div><div class="stat-grid"><div class="stat-card"><span>全部工单</span><strong>{{items.length}}</strong></div><div class="stat-card"><span>待派单</span><strong>{{items.filter(x=>x.Status==='reported').length}}</strong></div><div class="stat-card"><span>维修中</span><strong>{{items.filter(x=>['assigned','repairing'].includes(x.Status)).length}}</strong></div><div class="stat-card"><span>已关闭</span><strong>{{items.filter(x=>x.Status==='closed').length}}</strong></div></div><section class="card"><table v-if="items.length" class="data-table"><thead><tr><th>房源</th><th>报修内容</th><th>材料费用</th><th>状态</th><th>租客确认</th><th>操作</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td><strong>{{propertyName(x.PropertyID)}}</strong></td><td>{{x.Description}}</td><td>{{x.MaterialCost}}</td><td><span class="status-badge" :class="x.Status">{{x.Status}}</span></td><td>{{x.TenantConfirmed?'已确认':'待确认'}}</td><td><div class="action-group"><button v-if="x.Status==='reported'" class="secondary-button" @click="assign(x.ID)">派单</button><button v-if="x.Status==='assigned'" class="secondary-button" @click="transition(x.ID,'repairing')">开始维修</button><button v-if="x.Status==='repairing'" class="primary-button" @click="transition(x.ID,'completed')">维修完成</button><button v-if="x.Status==='completed'" class="primary-button" @click="confirm(x.ID)">租客确认</button></div></td></tr></tbody></table><div v-else class="empty-state"><b>暂无维修工单</b><span>点击右上角新增第一条报修</span></div></section><div v-if="showModal" class="modal-mask" @click.self="showModal=false"><div class="modal"><div class="modal-header"><h3>新增维修报修</h3><button class="close-button" @click="showModal=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>报修房源 *</span><select v-model="form.PropertyID"><option value="">请选择房源</option><option v-for="x in properties" :key="x.ID" :value="x.ID">{{x.Building}} · {{x.Room}}</option></select></label><label><span>关联租客</span><select v-model="form.TenantID"><option value="">无关联租客</option><option v-for="x in tenants" :key="x.ID" :value="x.ID">{{x.Name}} · {{x.Phone}}</option></select></label><label class="full"><span>报修内容 *</span><textarea v-model="form.Description" rows="4" placeholder="请描述故障位置和具体问题"></textarea></label></div></div><div class="modal-footer"><button class="secondary-button" @click="showModal=false">取消</button><button class="primary-button" @click="add">提交报修</button></div></div></div></div></template>